Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
const int MAXN = 15000;
struct Edge {
    int to, capacity, flow, cost;
};
vector<Edge> edges;
vector<int> adj[MAXN];
long long total_cost, dist[MAXN];
int n, m, k, c, d, p[MAXN], pe[MAXN], inq[MAXN], s=9998, t=9999, cur, i, j;
void add_edge(int u, int v, int cap, int cst) {
    adj[u].push_back(edges.size()); edges.push_back({v, cap, 0, cst});
    adj[v].push_back(edges.size()); edges.push_back({u, 0, 0, -cst});
}
void run() {
    fill(dist, dist + 10000, (long long)1e18);
    fill(p, p + 10000, -1);
    fill(pe, pe + 10000, -1);
    fill(inq, inq + 10000, 0);
    dist[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = 1;
    cur = t;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        inq[u] = 0;
        for (auto e_idx : adj[u]) {
            if (edges[e_idx].capacity - edges[e_idx].flow == 0) continue;
            int cst = edges[e_idx].cost, y = edges[e_idx].to;
            if (dist[y] > dist[u] + cst) {
                dist[y] = dist[u] + cst;
                p[y] = u;
                pe[y] = e_idx;
                if (!inq[y]) { inq[y] = 1; q.push(y); }
            }
        }
    }
    int node = cur;
    while (node != s) {
        edges[pe[node]].flow++;
        edges[pe[node] ^ 1].flow--;
        node = p[node];
    }
    total_cost += dist[t];
}
int main() {
    cin >> n >> m >> k >> c >> d;
    int x, y;
    for (int i = 1; i <= k; i++) { cin >> x; x--; add_edge(s, x, 1, 0); }
    for (int i = 1; i <= 101; i++) add_edge((i - 1) * n, t, k, (i - 1) * c);
    for (int i = 1; i <= m; i++) {
        cin >> x >> y; x--; y--;
        for (int i = 1; i <= 100; i++) {
            for (int j = 1; j <= k; j++) {
                add_edge(x + (i - 1) * n, y + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                add_edge(y + (i - 1) * n, x + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= 100; j++) {
            add_edge(i - 1 + (j - 1) * n, i - 1 + (j - 1) * n + n, k, 0);
        }
    }
    for (int i = 1; i <= k; i++) run();
    cout << total_cost << endl;
    return 0;
}
